<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { api, type AgentSession, type Approval, type CandidateReport, type Dependencies, type Experiment, type ExperimentComparison, type ExperimentDesign, type ExperimentRun, type Factor, type Job, type ReportSeries, type ReportSummary, type ResearchPlan, type ResearchReview, type Strategy } from './api'
const activeTab = ref<'dashboard' | 'strategies' | 'experiments' | 'jobs' | 'factor_lab'>('dashboard'); const health=ref('unknown'); const loading=ref(false); const error=ref(''); const dependencies=ref<Dependencies|null>(null); const strategies=ref<Strategy[]>([]); const experiments=ref<Experiment[]>([]); const factors=ref<Factor[]>([]); const jobs=ref<Job[]>([]); const runsByExperiment=ref<Record<string,ExperimentRun[]>>({}); const selectedExperimentId=ref(''); const selectedStrategyId=ref(''); const selectedStrategyApprovals=ref<Approval[]>([]); const compareExperimentIds=ref<string[]>([]); const previewTitle=ref(''); const previewContent=ref(''); const factorEtf=ref(''); const factorDateFrom=ref(''); const factorDateTo=ref(''); const previewColumns=ref<string[]>([]); const previewRows=ref<string[][]>([]); const reportTitle=ref(''); const reportSummaries=ref<ReportSummary[]>([]); const strategyStatus=ref(''); const jobStatus=ref(''); const jobExperiment=ref(''); const strategyId=ref(''); const strategyName=ref(''); const experimentId=ref(''); const experimentObjective=ref(''); const runExperimentId=ref(''); const runTaskType=ref('factor_quality'); const runKey=ref(''); const trainingWindows=ref('500,750,1000'); const trainingSeeds=ref('7,42,123'); const submitting=ref(false); const researchObjective=ref(''); const researchBaseline=ref(''); const researchBudget=ref(10); const researchTasks=ref<string[]>(['factor_quality','factor_common_oos']); const planState=ref('draft'); const planCheck=ref<{valid:boolean;reason:string|null}|null>(null); const reviewer=ref(''); const cloneId=ref(''); const cloneName=ref(''); const experimentDesign=ref<ExperimentDesign|null>(null); const researchReview=ref<ResearchReview|null>(null); const agentMessage=ref(''); const agentSending=ref(false); const agentSessionId=ref(''); const agentState=ref<{session_id:string;session:{status:string}|null;tasks:Array<{id:string;task_type:string;status:string;payload:Record<string,unknown>}>;summary:{task_count:number;completed:number;failed:number;statuses:Record<string,number>};suggestions:Array<{action:string;reason:string;task_id?:string}>}|null>(null); const agentFeedback=ref<{outcome:string;completed:number;failed:number;metrics:Record<string,number|null>;suggestions:Array<{action:string;reason:string}>}|null>(null); const agentMessages=ref<Array<{role:'user'|'agent'; text:string}>>([{role:'agent',text:'你好，我可以把你的自然语言研究目标转换成受治理的实验计划。请描述你想验证的因子、模型、区间或成本条件。'}])
const comparison=ref<ExperimentComparison|null>(null)
const previewNumericPoints=computed(()=>{const values=previewRows.value.map(row=>Number(row[1])).filter(value=>Number.isFinite(value)); if(values.length<2)return ''; const min=Math.min(...values); const max=Math.max(...values); const span=max-min||1; return values.map((value,index)=>`${(index/(values.length-1))*100},${100-((value-min)/span)*90-5}`).join(' ')})
function seriesPoints(series: ReportSeries){const values=series.points.map(point=>point.y); if(values.length<2)return ''; const min=Math.min(...values); const max=Math.max(...values); const span=max-min||1; return series.points.map((point,index)=>`${(index/(series.points.length-1))*100},${100-((point.y-min)/span)*90-5}`).join(' ')}
function kindLabel(kind:string){return ({training_log:'训练日志',nav:'净值曲线',drawdown:'回撤',cost_sensitivity:'成本敏感性',rolling_window:'滚动窗口',report:'研究报告'} as Record<string,string>)[kind]||kind}
function pageLabel(tab:string){return ({dashboard:'研究工作台',strategies:'策略中心',experiments:'实验中心',jobs:'任务中心',factor_lab:'因子实验室'} as Record<string,string>)[tab]||tab}
function statusLabel(status:string){return ({unknown:'未知',queued:'排队中',running:'运行中',retrying:'重试中',succeeded:'已完成',completed:'已完成',failed:'失败',cancelled:'已取消',draft:'草稿',drafted:'已生成',validated:'已校验',over_budget:'超出预算',approved:'已批准',candidate:'候选',research:'研究中',active:'启用',frozen:'已冻结',retired:'已归档'} as Record<string,string>)[status]||status}
const readyCount=computed(()=>dependencies.value?[dependencies.value.database,dependencies.value.redis].filter(x=>x.reachable).length:0); const activeJobs=computed(()=>jobs.value.filter(x=>['queued','running','retrying'].includes(x.status)).length); const filteredStrategies=computed(()=>strategies.value.filter(x=>!strategyStatus.value||x.status===strategyStatus.value)); const factorJobs=computed(()=>jobs.value.filter(x=>{const key=(x.run_key||'').toLowerCase(); return ['quality','stratified','correlation','decay','regime'].some(n=>key.includes(n))&&(!jobExperiment.value||x.experiment_id===jobExperiment.value)&&(!factorEtf.value||key.includes(factorEtf.value.toLowerCase()))&&(!factorDateFrom.value||key.includes(factorDateFrom.value))&&(!factorDateTo.value||key.includes(factorDateTo.value))}))
const formatJson=(v:unknown)=>JSON.stringify(v,null,2)
const candidateReports=ref<Record<string,CandidateReport>>({})
const taskOptions=[['factor_quality','因子质量检查'],['factor_correlation','因子相关性分析'],['factor_common_train','因子训练'],['factor_common_oos','样本外验证'],['factor_sensitivity','成本 / Top-K 敏感性']] as const
const estimatedRuns=computed(()=>researchTasks.value.length)
const researchPlan=computed<ResearchPlan>(()=>({goal:{objective:researchObjective.value,baseline_strategy_id:researchBaseline.value||null,constraints:[],budget:Number(researchBudget.value)||1},tasks:researchTasks.value,estimated_runs:estimatedRuns.value,requires_approval:true}))
function toggleResearchTask(task:string){researchTasks.value=researchTasks.value.includes(task)?researchTasks.value.filter(item=>item!==task):[...researchTasks.value,task]}
async function validateResearchPlan(){try{const result=await api.validatePlan(researchPlan.value);planCheck.value={valid:result.valid,reason:result.reason};planState.value=result.valid?'validated':'over-budget'}catch(err){error.value=err instanceof Error?err.message:'计划校验失败'}}
async function draftResearchPlan(){try{const result=await api.draftPlan({objective:researchObjective.value,baseline_strategy_id:researchBaseline.value||null,constraints:[],budget:Number(researchBudget.value)||1});researchTasks.value=result.tasks;planState.value='drafted';planCheck.value=null}catch(err){error.value=err instanceof Error?err.message:'计划生成失败'}}
async function sendAgentMessage(){const message=agentMessage.value.trim();if(!message||agentSending.value)return;agentMessages.value.push({role:'user',text:message});agentMessage.value='';agentSending.value=true;researchObjective.value=message;try{const result=await api.draftPlan({objective:message,baseline_strategy_id:researchBaseline.value||null,constraints:[],budget:Number(researchBudget.value)||1});researchTasks.value=result.tasks;planState.value='drafted';planCheck.value=null;agentMessages.value.push({role:'agent',text:`已生成研究计划：${result.tasks.join('、') || '暂无匹配任务'}。预计运行 ${result.estimated_runs} 次。你可以在下方继续校验、设计矩阵或确认计划。`})}catch(err){const text=err instanceof Error?err.message:'Agent 请求失败';agentMessages.value.push({role:'agent',text:`处理失败：${text}`});error.value=text}finally{agentSending.value=false}}
async function confirmResearchPlan(){try{const result=await api.confirmPlan(researchPlan.value);planState.value=result.status;planCheck.value={valid:true,reason:null}}catch(err){error.value=err instanceof Error?err.message:'计划确认失败'}}
async function executeResearchPlan(){try{const result=await api.executePlan(researchPlan.value);agentSessionId.value=result.session.id;planState.value='running';planCheck.value={valid:true,reason:null};agentMessages.value.push({role:'agent',text:`计划已执行，已创建 ${result.queued.length} 个研究任务。系统会持续更新任务状态。`});await Promise.all([refresh(),refreshAgentState()])}catch(err){error.value=err instanceof Error?err.message:'计划执行失败'}}
async function refreshAgentFeedback(){if(!agentSessionId.value)return;try{agentFeedback.value=await api.agentFeedback(agentSessionId.value)}catch(err){if(err instanceof Error)error.value=err.message}}
async function createNextResearchPlan(){if(!agentSessionId.value)return;try{const result=await api.agentNextPlan(agentSessionId.value);researchObjective.value=result.plan.goal.objective;researchTasks.value=result.plan.tasks;researchBudget.value=result.plan.goal.budget;planState.value='drafted';planCheck.value=null;agentMessages.value.push({role:'agent',text:`已根据上一轮反馈生成下一轮计划：${result.plan.tasks.join('、')}。请校验计划后再确认执行。`})}catch(err){error.value=err instanceof Error?err.message:'下一轮计划生成失败'}}
async function exportAgentMarkdown(){if(!agentSessionId.value)return;try{const blob=await api.agentMarkdownReport(agentSessionId.value);const url=URL.createObjectURL(blob);const anchor=document.createElement('a');anchor.href=url;anchor.download=`研究报告-${agentSessionId.value}.md`;anchor.click();URL.revokeObjectURL(url)}catch(err){error.value=err instanceof Error?err.message:'研究报告导出失败'}}
async function refreshAgentState(){if(!agentSessionId.value)return;try{agentState.value=await api.agentState(agentSessionId.value);if(agentState.value.session?.status==='completed')planState.value='completed';if(agentState.value.summary.failed>0||agentState.value.summary.completed===agentState.value.summary.task_count)await refreshAgentFeedback()}catch(err){if(err instanceof Error)error.value=err.message}}
async function cancelResearchPlan(){try{await api.cancelPlan(researchPlan.value);planState.value='cancelled'}catch(err){error.value=err instanceof Error?err.message:'计划取消失败'}}
async function designResearchExperiments(){try{experimentDesign.value=await api.designPlan({tasks:researchTasks.value,training_windows:[500,750,1000],seeds:[7,42,123],cost_rates:[0.003,0.005],max_experiments:12,budget:Number(researchBudget.value)||1})}catch(err){error.value=err instanceof Error?err.message:'实验矩阵生成失败'}}
async function reviewResearchPlan(){try{researchReview.value=await api.reviewPlan({config:{tasks:researchTasks.value,training_windows:[500,750,1000],seeds:[7,42,123],cost_rates:[0.003,0.005],oos:researchTasks.value.includes('factor_common_oos'),embargo_days:0},metrics:{}})}catch(err){error.value=err instanceof Error?err.message:'研究评审失败'}}
function heatColor(value:string){const n=Number(value); if(!Number.isFinite(n))return {}; const alpha=Math.min(Math.abs(n),1)*0.65; return {backgroundColor:n>=0?`rgba(77,190,150,${alpha})`:`rgba(214,102,117,${alpha})`}}
async function refresh(){loading.value=true;try{const[h,d,s,e,f,j]=await Promise.all([api.health(),api.dependencies(),api.strategies(),api.experiments(),api.factors(),api.jobs(jobStatus.value||undefined)]);health.value=h.status;dependencies.value=d;strategies.value=s;experiments.value=e;factors.value=f.filter((item): item is Factor => 'factor_id' in item);jobs.value=j;const pairs=await Promise.all(e.map(async x=>[x.id,await api.runs(x.id)] as const));runsByExperiment.value=Object.fromEntries(pairs)}catch(err){error.value=err instanceof Error?err.message:'刷新数据失败'}finally{loading.value=false}}
async function createStrategy(){submitting.value=true;try{await api.createStrategy({strategy_id:strategyId.value,name:strategyName.value});strategyId.value='';strategyName.value='';await refresh()}catch(err){error.value=err instanceof Error?err.message:'创建策略失败'}finally{submitting.value=false}}
async function createExperiment(){submitting.value=true;try{await api.createExperiment({experiment_id:experimentId.value,objective:experimentObjective.value,config:{source:'platform-ui'}});experimentId.value='';experimentObjective.value='';await refresh()}catch(err){error.value=err instanceof Error?err.message:'创建实验失败'}finally{submitting.value=false}}
async function createRun(){submitting.value=true;try{await api.createRun(runExperimentId.value,{run_key:runKey.value,task_type:runTaskType.value,config:{source:'platform-ui',data_dir:'quotes2',training_windows:trainingWindows.value.split(',').map(Number).filter(Number.isFinite),seeds:trainingSeeds.value.split(',').map(Number).filter(Number.isFinite)}});runKey.value='';await refresh();activeTab.value='jobs'}catch(err){error.value=err instanceof Error?err.message:'提交运行失败'}finally{submitting.value=false}}
async function copyExperiment(x:Experiment){try{await api.createExperiment({experiment_id:`${x.experiment_id}_copy_${Date.now()}`,objective:`${x.objective} (copy)`,config:{...x.config,copied_from:x.experiment_id,source:'platform-copy'}});await refresh()}catch(err){error.value=err instanceof Error?err.message:'复制实验失败'}}
async function cancelJob(x:Job){try{await api.cancelJob(x.id);await refresh()}catch(err){error.value=err instanceof Error?err.message:'取消任务失败'}}
async function retryJob(x:Job){try{await api.retryJob(x.id);await refresh()}catch(err){error.value=err instanceof Error?err.message:'重试任务失败'}}
async function showReport(job:Job){try{const x=await api.jobReport(job.id);reportTitle.value=job.run_key||job.id;reportSummaries.value=x.summaries}catch(err){error.value=err instanceof Error?err.message:'生成报告失败'}}
function exportCurrentReport(){if(!reportTitle.value)return;const payload={title:reportTitle.value,summaries:reportSummaries.value,exported_at:new Date().toISOString()};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const anchor=document.createElement('a');anchor.href=url;anchor.download=`研究报告-${reportTitle.value}.json`;anchor.click();URL.revokeObjectURL(url)}
async function previewArtifact(id:string,title:string){try{const x=await api.artifactPreview(id);previewTitle.value=title;previewContent.value=x.content;previewColumns.value=x.columns;previewRows.value=x.rows}catch(err){error.value=err instanceof Error?err.message:'预览产物失败'}}
async function selectStrategy(id:string){selectedStrategyId.value=selectedStrategyId.value===id?'':id; if(selectedStrategyId.value){try{selectedStrategyApprovals.value=await api.strategyApprovals(id)}catch(err){error.value=err instanceof Error?err.message:'查询审批记录失败'}}else selectedStrategyApprovals.value=[]}
async function submitStrategyDecision(strategy:Strategy, decision:'approved'|'freeze_requested'){if(!reviewer.value){error.value='请输入审批人';return}try{await api.submitApproval({target_type:'strategy',target_id:strategy.id,decision,reviewer:reviewer.value,comment:`${decision} from 策略中心`});await refresh();await selectStrategy(strategy.id)}catch(err){error.value=err instanceof Error?err.message:'提交审批失败'}}
async function transitionStrategy(strategy:Strategy,status:string){try{await api.transitionStrategy(strategy.id,status,'策略中心 lifecycle action');await refresh();await selectStrategy(strategy.id)}catch(err){error.value=err instanceof Error?err.message:'状态切换失败'}}
async function cloneStrategy(strategy:Strategy){if(!cloneId.value||!cloneName.value){error.value='请输入克隆策略 ID 和名称';return}try{await api.cloneStrategy(strategy.id,{strategy_id:cloneId.value,name:cloneName.value});cloneId.value='';cloneName.value='';await refresh()}catch(err){error.value=err instanceof Error?err.message:'克隆策略失败'}}
async function selectExperiment(id:string){selectedExperimentId.value=selectedExperimentId.value===id?'':id; if(selectedExperimentId.value&&!candidateReports.value[id]){try{candidateReports.value[id]=await api.candidateReport(id)}catch(err){error.value=err instanceof Error?err.message:'候选报告加载失败'}}} const toggleCompare=(id:string)=>{compareExperimentIds.value=compareExperimentIds.value.includes(id)?compareExperimentIds.value.filter(x=>x!==id):[...compareExperimentIds.value,id].slice(-3)}
async function refreshComparison(){if(compareExperimentIds.value.length<1){comparison.value=null;return}try{comparison.value=await api.compareExperiments(compareExperimentIds.value)}catch(err){error.value=err instanceof Error?err.message:'实验对比加载失败'}}
async function toggleCompareAndRefresh(id:string){toggleCompare(id);await refreshComparison()}
let timer:ReturnType<typeof setInterval>|undefined;let agentTimer:ReturnType<typeof setInterval>|undefined;onMounted(()=>{refresh();timer=setInterval(()=>{if(!loading.value)refresh()},15000);agentTimer=setInterval(()=>{refreshAgentState()},5000)});onUnmounted(()=>{if(timer)clearInterval(timer);if(agentTimer)clearInterval(agentTimer)})
</script>

<template>
  <section v-if="agentFeedback" class="panel phase10-agent-actions"><div class="panel-heading"><div><p class="eyebrow">Phase 10</p><h3>研究结果处理</h3></div><span class="tag">只读分析</span></div><p class="muted">基于当前会话反馈生成下一轮待确认计划，或下载中文 Markdown 报告。</p><div class="agent-actions"><button class="ghost-button" @click="createNextResearchPlan">生成下一轮计划</button><button class="ghost-button" @click="exportAgentMarkdown">导出中文 Markdown 报告</button></div></section>
  <section v-if="activeTab === 'experiments' && compareExperimentIds.length" class="panel phase10-comparison"><div class="panel-heading"><div><p class="eyebrow">Phase 10</p><h3>实验指标对比</h3></div><button class="ghost-button" @click="refreshComparison">刷新指标</button></div><div v-if="comparison" class="compare-grid"><div v-for="row in comparison.experiments" :key="row.id" class="compare-card"><strong>{{ row.experiment_id }}</strong><span>完成 {{ row.completed_runs }} / {{ row.runs }}，失败 {{ row.failed_runs }}</span><span v-for="metric in ['total_return_net','max_drawdown','sharpe','turnover']" :key="metric" class="tag">{{ metric }}：{{ row.metrics[metric] ?? '无' }}</span></div></div><p v-else class="muted">点击“刷新指标”加载选中实验的真实产物指标。</p></section>
  <div class="app-shell">
    <aside class="sidebar">
      <div class="brand"><div class="brand-mark">S</div><div><strong>StockRNN</strong><span>量化研究平台</span></div></div>
      <nav>
        <button :class="{ active: activeTab === 'dashboard' }" @click="activeTab = 'dashboard'">研究工作台</button>
        <button :class="{ active: activeTab === 'strategies' }" @click="activeTab = 'strategies'">策略中心</button>
        <button :class="{ active: activeTab === 'experiments' }" @click="activeTab = 'experiments'">实验中心</button>
        <button :class="{ active: activeTab === 'jobs' }" @click="activeTab = 'jobs'">任务中心</button>
        <button :class="{ active: activeTab === 'factor_lab' }" @click="activeTab = 'factor_lab'">因子实验室</button>
      </nav>
      <div class="sidebar-note"><span class="dot green"></span><div><small>平台状态</small><strong>{{ health === 'ok' ? 'API 正常' : '检查中' }}</strong></div></div>
    </aside>
    <main class="main-content">
      <header class="topbar"><div><p class="eyebrow">量化研究系统</p><h1>{{ pageLabel(activeTab) }}</h1></div><button class="ghost-button" :disabled="loading" @click="refresh">{{ loading ? '刷新中...' : '刷新数据' }}</button></header>
      <div v-if="error" class="alert">{{ error }} <button @click="error = ''">关闭</button></div>
      <section v-if="activeTab === 'dashboard'" class="page-grid">
        <div class="hero-card card-span-2"><div><p class="eyebrow light">研究工作台</p><h2>把研究想法<br /><em>变成可验证的实验</em></h2><p class="hero-copy">统一管理因子假设、训练、验证和回测。</p></div><div class="hero-orbit"><span>因子</span><span>训练</span><span>验证</span></div></div>
        <div class="metric-card"><span>策略</span><strong>{{ strategies.length }}</strong><small>已登记记录</small></div><div class="metric-card"><span>实验</span><strong>{{ experiments.length }}</strong><small>研究目标</small></div><div class="metric-card"><span>任务</span><strong>{{ jobs.length }}</strong><small>{{ activeJobs }} 个活跃任务</small></div><div class="metric-card wide"><span>基础设施</span><strong>{{ readyCount }}/2</strong><small>MySQL / Redis 可连接</small></div>
        <div class="panel agent-console card-span-2"><div class="panel-heading"><div><p class="eyebrow">智能 Agent</p><h3>用自然语言下达研究指令</h3></div><span class="tag">受治理 Agent</span></div><div class="agent-disclaimer">当前 Agent 负责研究规划和任务编排，不执行任意代码、不直接修改数据库、不自动下单。</div><div class="agent-thread"><div v-for="(message,index) in agentMessages" :key="index" class="agent-message" :class="message.role"><span>{{ message.role === 'agent' ? 'Agent' : 'You' }}</span><p>{{ message.text }}</p></div></div><div class="agent-composer"><textarea v-model="agentMessage" placeholder="例如：比较过去三年动量和成交量因子，在不同成本率下做样本外验证" @keydown.ctrl.enter.prevent="sendAgentMessage"></textarea><button class="primary-button" :disabled="agentSending || !agentMessage.trim()" @click="sendAgentMessage">{{ agentSending ? '处理中...' : '发送指令' }}</button></div><div class="agent-actions"><button class="primary-button" :disabled="agentSending || !researchObjective || !planCheck?.valid" @click="executeResearchPlan">确认并执行</button><button class="ghost-button" @click="activeTab = 'jobs'">查看任务</button></div><div v-if="agentState" class="agent-runtime"><div class="agent-runtime-heading"><strong>执行状态</strong><span class="status" :class="agentState.session?.status">{{ statusLabel(agentState.session?.status || 'unknown') }}</span><span class="muted">{{ agentState.summary.completed }}/{{ agentState.summary.task_count }} 已完成，失败 {{ agentState.summary.failed }}</span></div><div class="agent-task-list"><div v-for="task in agentState.tasks" :key="task.id" class="agent-task-row"><span>{{ task.task_type }}</span><span class="status" :class="task.status">{{ statusLabel(task.status) }}</span><small v-if="task.payload?.error" class="error-text">{{ task.payload.error }}</small></div></div><div v-if="agentState.suggestions.length" class="agent-suggestions"><strong>下一步建议</strong><span v-for="suggestion in agentState.suggestions" :key="suggestion.action + (suggestion.task_id || '')">{{ suggestion.reason }}</span></div><div v-if="agentFeedback" class="agent-feedback"><div class="agent-runtime-heading"><strong>研究结果分析</strong><span class="status" :class="agentFeedback.outcome">{{ statusLabel(agentFeedback.outcome) }}</span></div><div class="feedback-metrics"><span v-for="(value,key) in agentFeedback.metrics" :key="key" class="tag">{{ key }}={{ value ?? '无' }}</span></div><div class="agent-suggestions"><strong>下一轮研究建议</strong><span v-for="suggestion in agentFeedback.suggestions" :key="suggestion.action">{{ suggestion.reason }}</span></div></div></div></div>
        <div class="panel plan-panel card-span-2"><div class="panel-heading"><div><p class="eyebrow">研究计划</p><h3>生成受治理的研究计划</h3></div><span class="status" :class="planState">{{ statusLabel(planState) }}</span></div><div class="plan-form"><textarea v-model="researchObjective" placeholder="研究目标"></textarea><div class="form-row"><select v-model="researchBaseline"><option value="">不选择基准策略</option><option v-for="strategy in strategies" :key="strategy.id" :value="strategy.strategy_id">{{ strategy.strategy_id }}</option></select><input v-model.number="researchBudget" type="number" min="1" max="1000" placeholder="预算" /></div><div class="task-picker"><label v-for="[task,label] in taskOptions" :key="task" class="task-option"><input type="checkbox" :checked="researchTasks.includes(task)" @change="toggleResearchTask(task)" />{{ label }}</label></div><div class="plan-footer"><span class="muted">{{ estimatedRuns }} 预计运行次数 / 预算 {{ researchBudget }}</span><span v-if="planCheck" class="plan-message" :class="{invalid: !planCheck.valid}">{{ planCheck.reason || '计划未超出预算。' }}</span><div class="quick-actions"><button class="ghost-button" :disabled="!researchObjective || submitting" @click="draftResearchPlan">生成计划</button><button class="ghost-button" :disabled="!researchObjective || submitting" @click="validateResearchPlan">校验计划</button><button class="ghost-button" :disabled="!researchObjective || submitting" @click="designResearchExperiments">设计实验矩阵</button><button class="primary-button" :disabled="!researchObjective || !planCheck?.valid || submitting" @click="confirmResearchPlan">确认计划</button><button class="ghost-button" :disabled="submitting" @click="cancelResearchPlan">取消</button></div></div><div v-if="experimentDesign" class="design-result"><div class="panel-heading"><strong>实验矩阵</strong><span class="tag">{{ experimentDesign.estimated_runs }} / {{ experimentDesign.budget }} 次运行</span></div><p class="plan-message" :class="{invalid: !experimentDesign.valid}">{{ experimentDesign.reason || experimentDesign.rationale.join(' ') }}</p><div class="matrix-list"><span v-for="(experiment,index) in experimentDesign.experiments" :key="index" class="tag">{{ experiment.task }} / {{ experiment.training_window }}d / 随机种子 {{ experiment.seed }} / 成本 {{ experiment.cost_rate }}</span></div></div></div></div>
      </section>
      <section v-else-if="activeTab === 'strategies'" class="content-section">
        <div class="section-intro"><div><p class="eyebrow">策略登记</p><h2>策略中心</h2><p>已冻结策略仅可读取。</p></div><div class="filter-row"><select v-model="strategyStatus"><option value="">全部状态</option><option value="frozen">已冻结</option><option value="research">研究中</option><option value="active">启用</option></select><span class="tag">{{ filteredStrategies.length }} 条记录</span></div></div>
        <div class="panel create-panel"><h3>创建研究策略</h3><div class="form-row"><input v-model="strategyId" placeholder="strategy_id" /><input v-model="strategyName" placeholder="策略名称" /><button class="primary-button" :disabled="submitting || !strategyId || !strategyName" @click="createStrategy">创建</button></div></div>
         <div class="panel table-panel"><div v-if="!filteredStrategies.length" class="empty">暂无策略。</div><table v-else><thead><tr><th>策略</th><th>状态</th><th>版本数</th><th>策略属性</th></tr></thead><tbody><template v-for="strategy in filteredStrategies" :key="strategy.id"><tr><td><button class="link-button" @click="selectStrategy(strategy.id)"><code>{{ strategy.strategy_id }}</code></button><br /><small class="muted">父策略={{ strategy.parent_strategy_id || '根策略' }}</small></td><td><span class="status" :class="strategy.status">{{ statusLabel(strategy.status) }}</span></td><td>{{ strategy.versions.length }}</td><td><span v-if="strategy.status === 'frozen'" class="tag frozen-badge">已冻结，只读</span><span v-else-if="strategy.status === 'candidate'" class="tag candidate-badge">候选待评审</span><span v-else class="muted">研究版本</span></td></tr><tr v-if="selectedStrategyId === strategy.id" class="detail-row"><td colspan="4"><div class="version-list"><div v-for="version in strategy.versions" :key="version.id" class="version-card"><strong>{{ version.version }}</strong><span>{{ version.status }}</span><pre>{{ formatJson(version.config) }}</pre></div><div class="strategy-actions"><input v-model="reviewer" placeholder="审批人" /><button v-if="strategy.status === 'candidate'" class="primary-button" @click="submitStrategyDecision(strategy,'approved')">批准候选策略</button><button v-if="strategy.status === 'approved'" class="primary-button" @click="submitStrategyDecision(strategy,'freeze_requested')">申请冻结</button><button v-if="strategy.status === 'candidate'" class="ghost-button" @click="transitionStrategy(strategy,'research')">退回研究</button><button v-if="strategy.status === 'approved'" class="ghost-button" @click="transitionStrategy(strategy,'frozen')">审批后冻结</button><button v-if="strategy.status !== 'retired' && strategy.status !== 'frozen'" class="danger-button" @click="transitionStrategy(strategy,'retired')">归档</button></div><div v-if="strategy.status === 'frozen'" class="clone-panel"><input v-model="cloneId" placeholder="新策略 ID" /><input v-model="cloneName" placeholder="克隆名称" /><button class="ghost-button" @click="cloneStrategy(strategy)">克隆冻结基线</button></div><div v-if="selectedStrategyApprovals.length" class="approval-list"><small class="muted">审批历史</small><div v-for="approval in selectedStrategyApprovals" :key="approval.id"><span class="tag">{{ approval.decision }}</span> {{ approval.reviewer }} <span class="muted">{{ approval.comment }}</span></div></div></div></td></tr></template></tbody></table></div>
      </section>
      <section v-else-if="activeTab === 'experiments'" class="content-section">
        <div class="section-intro"><div><p class="eyebrow">实验跟踪</p><h2>实验中心</h2><p>创建、提交、复制和对比研究实验。</p></div><span class="tag">{{ experiments.length }} 条记录</span></div>
        <div class="panel create-panel"><h3>创建实验</h3><div class="form-row"><input v-model="experimentId" placeholder="experiment_id" /><input v-model="experimentObjective" placeholder="实验目标" /><button class="primary-button" :disabled="submitting || !experimentId || !experimentObjective" @click="createExperiment">创建</button></div></div>
        <div class="panel create-panel"><h3>提交研究运行</h3><div class="form-row"><select v-model="runExperimentId"><option value="">选择实验</option><option v-for="experiment in experiments" :key="experiment.id" :value="experiment.id">{{ experiment.experiment_id }}</option></select><select v-model="runTaskType"><option value="factor_quality">因子质量</option><option value="factor_stratified_returns">分层收益</option><option value="transformer_train">Transformer 训练</option><option value="factor_correlation">因子相关性</option><option value="factor_decay">因子衰减</option><option value="factor_regime">因子市场状态</option><option value="factor_sensitivity">敏感性分析</option><option value="factor_common_oos">因子样本外</option></select><input v-model="runKey" placeholder="run_key" /><input v-model="trainingWindows" placeholder="窗口：500,750,1000" /><input v-model="trainingSeeds" placeholder="随机种子： 7,42,123" /><button class="primary-button" :disabled="submitting || !runExperimentId || !runKey" @click="createRun">提交</button></div></div>
         <div class="panel table-panel"><div v-if="!experiments.length" class="empty">暂无实验。</div><table v-else><thead><tr><th>对比</th><th>实验</th><th>状态</th><th>运行 / 产物</th><th>操作</th></tr></thead><tbody><template v-for="experiment in experiments" :key="experiment.id"><tr><td><input type="checkbox" :checked="compareExperimentIds.includes(experiment.id)" @change="toggleCompare(experiment.id)" /></td><td><button class="link-button" @click="selectExperiment(experiment.id)"><code>{{ experiment.experiment_id }}</code></button><br />{{ experiment.objective }}</td><td><span class="status" :class="experiment.status">{{ statusLabel(experiment.status) }}</span></td><td>{{ (runsByExperiment[experiment.id] || []).length }} / {{ (runsByExperiment[experiment.id] || []).reduce((sum, run) => sum + run.artifacts.length, 0) }}</td><td><button class="ghost-button" @click="copyExperiment(experiment)">复制</button></td></tr><tr v-if="selectedExperimentId === experiment.id" class="detail-row"><td colspan="5"><pre>{{ formatJson(experiment.config) }}</pre></td></tr></template></tbody></table></div>
        <div v-if="compareExperimentIds.length" class="panel compare-panel"><h3>实验对比</h3><div class="compare-grid"><div v-for="id in compareExperimentIds" :key="id" class="compare-card"><strong>{{ experiments.find(item => item.id === id)?.experiment_id }}</strong><span>{{ experiments.find(item => item.id === id)?.objective }}</span></div></div></div>
      </section>
       <section v-else-if="activeTab === 'jobs'" class="content-section"><div class="section-intro"><h2>任务中心</h2><div class="filter-row"><select v-model="jobStatus" @change="refresh"><option value="">全部状态</option><option value="queued">排队中</option><option value="running">运行中</option><option value="succeeded">已完成</option><option value="failed">失败</option></select><span class="tag">{{ jobs.length }} 个任务</span></div></div><div class="panel table-panel"><table v-if="jobs.length"><thead><tr><th>状态</th><th>进度</th><th>轮次</th><th>运行</th><th>产物</th><th>操作</th></tr></thead><tbody><tr v-for="job in jobs" :key="job.id"><td>{{ statusLabel(job.status) }}</td><td>{{ Math.round(job.progress) }}%</td><td>{{ job.current_epoch != null ? `${job.current_epoch}/${job.total_epochs || '?'}` : '—' }}</td><td><code>{{ job.run_key || job.id }}</code></td><td>{{ job.artifacts.length }}</td><td><button class="ghost-button" @click="showReport(job)">报告</button><button v-if="['queued','running','retrying'].includes(job.status)" class="danger-button" @click="cancelJob(job)">取消</button><button v-else-if="job.status === 'failed'" class="ghost-button" @click="retryJob(job)">重试</button></td></tr></tbody></table><div v-else class="empty">暂无任务。</div></div><div v-if="reportTitle" class="panel preview-panel"><div class="panel-heading"><h3>报告：{{ reportTitle }}</h3><div class="agent-actions"><button class="ghost-button" @click="exportCurrentReport">导出报告</button><button class="ghost-button" @click="reportTitle = ''">关闭</button></div></div><div v-for="summary in reportSummaries" :key="summary.relative_path" class="report-summary"><div class="report-heading"><strong>{{ kindLabel(summary.kind) }}</strong><span class="tag">{{ summary.artifact_type }}</span></div><code>{{ summary.relative_path }}</code><div v-if="Object.keys(summary.metrics).length" class="metric-tags"><span v-for="(value,key) in summary.metrics" :key="key" class="tag">{{ key }}={{ value }}</span></div><div v-for="series in summary.series" :key="series.name" class="series-block"><div class="series-label">{{ series.name }}</div><svg class="metric-chart" viewBox="0 0 100 100" preserveAspectRatio="none"><polyline :points="seriesPoints(series)" fill="none" stroke="#8de4bd" stroke-width="2" vector-effect="non-scaling-stroke" /></svg></div><table v-if="summary.columns.length" class="preview-table"><thead><tr><th v-for="column in summary.columns" :key="column">{{ column }}</th></tr></thead><tbody><tr v-for="(row,index) in summary.rows" :key="index"><td v-for="(cell,columnIndex) in row" :key="columnIndex">{{ cell }}</td></tr></tbody></table><pre v-if="summary.preview">{{ summary.preview }}</pre></div></div></section>
       <section v-else class="content-section"><div class="section-intro"><div><h2>因子实验室</h2><p class="muted">浏览因子定义、版本和研究产物。</p></div><div class="filter-row"><select v-model="jobExperiment"><option value="">全部实验</option><option v-for="experiment in experiments" :key="experiment.id" :value="experiment.id">{{ experiment.experiment_id }}</option></select><input v-model="factorEtf" placeholder="ETF / 标的" /><input v-model="factorDateFrom" type="date" /><input v-model="factorDateTo" type="date" /><span class="tag">{{ factorJobs.length }} 个因子任务</span></div></div><div v-if="factors.length" class="factor-cards"><article v-for="factor in factors" :key="factor.id" class="panel factor-card"><div class="factor-title"><div><strong>{{ factor.name }}</strong><code>{{ factor.factor_id }}</code></div><span class="status" :class="factor.status">{{ statusLabel(factor.status) }}</span></div><p class="factor-hypothesis">{{ factor.economic_hypothesis || '尚未记录经济假设。' }}</p><div v-for="version in factor.versions" :key="version.id" class="factor-version"><div class="factor-version-heading"><strong>{{ version.version }}</strong><span>{{ version.time_boundary || '未指定时间边界' }}</span></div><code class="formula">{{ version.formula }}</code><small>输入： {{ version.input_columns.join(', ') || '无' }}</small></div></article></div><div class="panel table-panel"><table v-if="factorJobs.length"><thead><tr><th>运行</th><th>状态</th><th>进度</th><th>产物</th></tr></thead><tbody><tr v-for="job in factorJobs" :key="job.id"><td>{{ job.run_key }}</td><td>{{ statusLabel(job.status) }}</td><td>{{ Math.round(job.progress) }}%</td><td><button v-for="artifact in job.artifacts" :key="artifact.id" class="artifact-chip" @click="previewArtifact(artifact.id, artifact.artifact_type)">{{ artifact.artifact_type }}</button></td></tr></tbody></table><div v-else class="empty">没有符合筛选条件的因子任务。</div></div><div v-if="previewTitle" class="panel preview-panel"><h3>{{ previewTitle }}</h3><svg v-if="previewNumericPoints" class="metric-chart" viewBox="0 0 100 100" preserveAspectRatio="none"><polyline :points="previewNumericPoints" fill="none" stroke="#8de4bd" stroke-width="2" vector-effect="non-scaling-stroke" /></svg><table v-if="previewColumns.length" class="preview-table"><thead><tr><th v-for="column in previewColumns" :key="column">{{ column }}</th></tr></thead><tbody><tr v-for="(row,index) in previewRows" :key="index"><td v-for="(cell,columnIndex) in row" :key="columnIndex" :style="heatColor(cell)">{{ cell }}</td></tr></tbody></table><pre>{{ previewContent }}</pre></div></section>
      <section v-if="Object.keys(candidateReports).length" class="content-section candidate-report-dock"><div v-for="report in Object.values(candidateReports)" :key="report.experiment_id" class="panel"><div class="panel-heading"><h3>候选汇总： {{ report.experiment_id }}</h3><span class="status" :class="report.recommendation.eligible ? 'approved' : 'research'">{{ statusLabel(report.recommendation.status) }}</span></div><p class="muted">{{ report.selection_policy }}</p><div class="metric-tags"><span class="tag">窗口 {{ report.coverage.windows.join(', ') || '无' }}</span><span class="tag">随机种子 {{ report.coverage.seeds.join(', ') || '无' }}</span><span class="tag">成本 {{ report.coverage.cost_rates.join(', ') || '无' }}</span><span class="tag">市场状态 {{ report.coverage.market_regimes.join(', ') || '无' }}</span><span class="tag">均值 {{ report.overall.mean ?? '无' }}</span><span class="tag">标准差 {{ report.overall.std ?? '无' }}</span></div><p v-if="report.recommendation.reason" class="plan-message invalid">{{ report.recommendation.reason }}</p><table v-if="report.groups.length" class="preview-table"><thead><tr><th>窗口</th><th>随机种子</th><th>成本</th><th>市场状态</th><th>收益均值</th><th>收益标准差</th></tr></thead><tbody><tr v-for="group in report.groups" :key="`${group.window}-${group.seed}-${group.cost_rate}-${group.regime}`"><td>{{ group.window }}</td><td>{{ group.seed }}</td><td>{{ group.cost_rate }}</td><td>{{ group.regime }}</td><td>{{ group.metrics.total_return_net?.mean ?? '无' }}</td><td>{{ group.metrics.total_return_net?.std ?? '无' }}</td></tr></tbody></table></div></section>
    </main>
  </div>
</template>
